// REQ-162 (docs/sims.md 4.3, 5.5): the fixed formatter for template slots,
// KPIs and the debrief. No Intl, no locale, no local time zone: dates are UTC
// arithmetic from the document's clock.start, which ECMAScript specifies to
// the millisecond on every engine.

import type { Value } from "./types.ts";

export interface ClockBase {
  kind: "clock" | "date";
  // seconds since midnight for "HH:MM"; epoch milliseconds (UTC) for dated sims
  dayStartSeconds: number;
  epochMs: number;
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function digits(s: string): boolean {
  if (!s.length) return false;
  for (let i = 0; i < s.length; i++) if (s[i] < "0" || s[i] > "9") return false;
  return true;
}

// "14:00" or "2027-02-01T09:00" (optionally with :SS). Returns null when malformed.
export function parseClockStart(start: string): ClockBase | null {
  const tIdx = start.indexOf("T");
  if (tIdx < 0) {
    const hm = start.split(":");
    if (hm.length < 2 || hm.length > 3 || !hm.every(digits)) return null;
    const h = Number(hm[0]);
    const m = Number(hm[1]);
    const s = hm.length === 3 ? Number(hm[2]) : 0;
    if (h > 23 || m > 59 || s > 59) return null;
    return { kind: "clock", dayStartSeconds: h * 3600 + m * 60 + s, epochMs: 0 };
  }
  const ymd = start.slice(0, tIdx).split("-");
  const hm = start.slice(tIdx + 1).split(":");
  if (ymd.length !== 3 || !ymd.every(digits) || hm.length < 2 || hm.length > 3 || !hm.every(digits)) return null;
  const y = Number(ymd[0]);
  const mo = Number(ymd[1]);
  const d = Number(ymd[2]);
  const h = Number(hm[0]);
  const mi = Number(hm[1]);
  const s = hm.length === 3 ? Number(hm[2]) : 0;
  if (mo < 1 || mo > 12 || d < 1 || d > 31 || h > 23 || mi > 59 || s > 59) return null;
  const ms = Date.UTC(y, mo - 1, d, h, mi, s);
  if (ms !== ms) return null;
  return { kind: "date", dayStartSeconds: h * 3600 + mi * 60 + s, epochMs: ms };
}

function pad2(n: number): string {
  return n < 10 ? `0${n}` : String(n);
}

export function fmtClock(base: ClockBase, seconds: number, withSeconds: boolean): string {
  const total = Math.floor(base.dayStartSeconds + seconds);
  const day = ((total % 86400) + 86400) % 86400;
  const h = Math.floor(day / 3600);
  const m = Math.floor(day / 60) % 60;
  const s = day % 60;
  return withSeconds ? `${pad2(h)}:${pad2(m)}:${pad2(s)}` : `${pad2(h)}:${pad2(m)}`;
}

function dateOf(base: ClockBase, seconds: number): Date {
  return new Date(base.epochMs + Math.floor(seconds) * 1000);
}

export function fmtDate(base: ClockBase, seconds: number): string {
  if (base.kind !== "date") return fmtClock(base, seconds, false);
  const d = dateOf(base, seconds);
  return `${DAYS[d.getUTCDay()]} ${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

export function fmtDateShort(base: ClockBase, seconds: number): string {
  if (base.kind !== "date") return fmtClock(base, seconds, false);
  const d = dateOf(base, seconds);
  return `${DAYS[d.getUTCDay()]} ${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`;
}

export function fmtDateTime(base: ClockBase, seconds: number): string {
  return base.kind === "date" ? `${fmtDate(base, seconds)} ${fmtClock(base, seconds, false)}` : fmtClock(base, seconds, false);
}

// Sim time for the renderer and the debrief timeline, by the document's calendar.
export function fmtSimTime(base: ClockBase, calendar: "clock" | "date" | "week" | undefined, seconds: number): string {
  if (calendar === "week") return `Week ${Math.floor(seconds / 604800) + 1}, ${fmtDateShort(base, seconds)}`;
  if (calendar === "date" || (calendar === undefined && base.kind === "date")) return fmtDateTime(base, seconds);
  return fmtClock(base, seconds, true);
}

export function fmtDuration(seconds: number): string {
  const s = Math.round(Math.abs(seconds));
  const sign = seconds < 0 ? "-" : "";
  if (s >= 86400) {
    const d = Math.floor(s / 86400);
    const h = Math.floor((s % 86400) / 3600);
    return `${sign}${d} d${h ? ` ${h} h` : ""}`;
  }
  if (s >= 3600) {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    return `${sign}${h} h${m ? ` ${m} min` : ""}`;
  }
  const m = Math.floor(s / 60);
  const sec = s % 60;
  return `${sign}${m} min ${pad2(sec)} s`;
}

export function fmtMinutes(seconds: number): string {
  const m = Math.round(seconds / 60);
  return m < 1 ? "<1 min" : `${m} min`;
}

// Fixed-point with a decimal point, half away from zero, no grouping.
export function fmtFixed(x: number, dp: number): string {
  if (x !== x) return "0";
  const neg = x < 0;
  let scaled = Math.abs(x);
  let mul = 1;
  for (let i = 0; i < dp; i++) mul *= 10;
  const n = Math.round(scaled * mul);
  const whole = Math.floor(n / mul);
  const frac = n - whole * mul;
  let fs = String(frac);
  while (fs.length < dp) fs = "0" + fs;
  const body = dp > 0 ? `${whole}.${fs}` : String(whole);
  return neg && n !== 0 ? `-${body}` : body;
}

export function fmtGrouped(n: number): string {
  const s = String(Math.abs(Math.round(n)));
  let out = "";
  for (let i = 0; i < s.length; i++) {
    const fromEnd = s.length - i;
    out += s[i];
    if (fromEnd > 1 && fromEnd % 3 === 1) out += ",";
  }
  return n < 0 ? `-${out}` : out;
}

export function fmtUsd(n: number): string {
  return n < 0 ? `-$${fmtGrouped(-n)}` : `$${fmtGrouped(n)}`;
}

export function fmtNumber(v: Value | undefined, precision: number | undefined): string {
  if (typeof v !== "number") return v === null || v === undefined ? "—" : typeof v === "string" ? v : String(v);
  if (precision === undefined) {
    // shortest round-trip, as JSON does; it is deterministic in ECMAScript
    return String(v);
  }
  return fmtFixed(v, precision);
}

// {expr|format}: the whitelist of formats a slot may name.
export function applyFormat(v: Value | undefined, format: string | null, base: ClockBase, calendar: "clock" | "date" | "week" | undefined): string {
  if (format === null) return fmtNumber(v, undefined);
  if (v === null || v === undefined) return "—";
  switch (format) {
    case "clock":
      return typeof v === "number" ? fmtClock(base, v, false) : "—";
    case "clocks":
      return typeof v === "number" ? fmtClock(base, v, true) : "—";
    case "date":
      return typeof v === "number" ? fmtDate(base, v) : "—";
    case "dateShort":
      return typeof v === "number" ? fmtDateShort(base, v) : "—";
    case "datetime":
      return typeof v === "number" ? fmtDateTime(base, v) : "—";
    case "time":
      return typeof v === "number" ? fmtSimTime(base, calendar, v) : "—";
    case "duration":
      return typeof v === "number" ? fmtDuration(v) : "—";
    case "min":
      return typeof v === "number" ? fmtMinutes(v) : "—";
    case "usd":
      return typeof v === "number" ? fmtUsd(v) : "—";
    case "usdk":
      return typeof v === "number" ? (Math.abs(v) >= 1000 ? `${v < 0 ? "-" : ""}$${fmtFixed(Math.abs(v) / 1000, Math.abs(v) >= 100000 ? 0 : 1)}k` : fmtUsd(v)) : "—";
    case "int":
      return typeof v === "number" ? fmtGrouped(v) : "—";
    case "0dp":
    case "1dp":
    case "2dp":
    case "3dp":
      return typeof v === "number" ? fmtFixed(v, Number(format[0])) : "—";
    case "pct":
      return typeof v === "number" ? `${fmtFixed(v, 0)}%` : "—";
    case "pct1":
      return typeof v === "number" ? `${fmtFixed(v, 1)}%` : "—";
    case "sign":
      return typeof v === "number" ? (v > 0 ? `+${fmtNumber(v, undefined)}` : fmtNumber(v, undefined)) : "—";
    case "yesno":
      return v === true ? "yes" : v === false ? "no" : "—";
    case "list":
      return Array.isArray(v) ? v.map((x) => fmtNumber(x, undefined)).join(", ") : fmtNumber(v, undefined);
    default:
      return fmtNumber(v, undefined);
  }
}

export const FORMATS = ["clock", "clocks", "date", "dateShort", "datetime", "time", "duration", "min", "usd", "usdk", "int", "0dp", "1dp", "2dp", "3dp", "pct", "pct1", "sign", "yesno", "list"];
